export const POLITICAL_IDEAS: PoliticalIdea[] = [
  {"kind":"governance","name":"Ancien régime","classed":"political system","said":"The ancien régime (; French: [ɑ̃sjɛ̃ ʁeʒim]; lit. 'former regime') was the political and social system of the Kingdom of France that the French Revolution overturned. This was accomplished through its abolition in 1790 of the feudal system of the French nobility, the declaration of a republic in 1792, and the execution of Louis XVI in 1793. \"Ancien régime\" is now a common metaphor for \"a system or mode no longer prevailing\".","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/ancien-regime"},{"label":"Wikipedia — Ancien régime","url":"https://en.wikipedia.org/wiki/Ancien_r%C3%A9gime"}]},
  {"kind":"governance","name":"Aristocracy","classed":"form of government","said":"Aristocracy (from Ancient Greek ἀριστοκρατίᾱ (aristokratíā) 'rule of the best'; from ἄριστος (áristos) 'best' and κράτος (krátos) 'power, strength') is a form of government that places power in the hands of a small, privileged ruling class, the aristocrats. Across Europe, the aristocracy exercised immense economic, political, and social influence. In Western Christian countries, the aristocracy was mostly equal with magnates, also known as the titled or higher nobility, however the members of the more numerous social class, the untitled lower nobility (petty nobility or gentry) were not part of the aristocracy.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/aristocracy"},{"label":"Wikipedia — Aristocracy","url":"https://en.wikipedia.org/wiki/Aristocracy"}]},
  {"kind":"governance","name":"Bureaucracy","classed":"political system","said":"Bureaucracy ( bure-OK-rə-see) is a system of organization where laws or regulatory authority are implemented by civil servants (non-elected officials). Historically, a bureaucracy was a government administration managed by departments staffed with non-elected officials. Today, bureaucracy is the administrative system governing any large institution, whether publicly owned or privately owned. The public administration in many jurisdictions is an example of bureaucracy, as is any centralized hierarchical structure of an institution, including corporations, societies, nonprofit organizations, and clubs.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/bureaucracy"},{"label":"Wikipedia — Bureaucracy","url":"https://en.wikipedia.org/wiki/Bureaucracy"}]},
  {"kind":"governance","name":"Cloistered rule","classed":"form of government","said":"Cloistered rule (院政, insei; lit. \"monastery administration\") was a form of government in Japan during the Heian period. In this bifurcated system, an emperor abdicated, but retained power and influence. Those retired emperors, who withdrew to live in monasteries (院, in), continued to act in ways intended to counterbalance the influence of Fujiwara regents and the warrior class. Simultaneously, the titular emperor, the former emperor's chosen successor, fulfilled all the ceremonial roles and formal duties of the monarchy. Retired emperors were called Daijō Tennō or Jōkō.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/insei"},{"label":"Wikipedia — Cloistered rule","url":"https://en.wikipedia.org/wiki/Cloistered_rule"}]},
  {"kind":"governance","name":"Confederation","classed":"form of government","said":"A confederation (also known as a confederacy or league) is a political union of sovereign states or chiefdoms united for purposes of common action. Usually created by a treaty, confederations of states tend to be established for dealing with critical issues, such as defence, foreign relations, internal trade or currency, with the central government being required to provide support for all its members. Confederalism represents a main form of intergovernmentalism, defined as any form of interaction around states that takes place on the basis of sovereign independence or government.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/confederation-politics"},{"label":"Wikipedia — Confederation","url":"https://en.wikipedia.org/wiki/Confederation"}]},
  {"kind":"governance","name":"Consociationalism","classed":"form of government","said":"Consociationalism ( kən-SOH-shee-AY-shən-əl-iz-əm) is a form of democratic power sharing. Political scientists define a consociational state as one which has major internal divisions along ethnic, religious, or linguistic lines, but which remains stable due to consultation among the elites of these groups. Consociational states are often contrasted with states with majoritarian electoral systems. The goals of consociationalism are governmental stability, the survival of the power-sharing arrangements, the survival of democracy, and the avoidance of violence.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/consociationalism"},{"label":"Wikipedia — Consociationalism","url":"https://en.wikipedia.org/wiki/Consociationalism"}]},
  {"kind":"governance","name":"Council–manager government","classed":"form of government","said":"The council–manager government is a form of local government commonly used for municipalities and counties in the United States, in Ireland, in city, district, and regional councils in New Zealand, and in Canadian municipalities. In the council-manager government, an elected city council hires a manager to serve as chief executive. The city manager can be replaced by a simple majority at any time, making it similar to the parliamentary system of national government, but with the difference that the city manager is a professional administrator rather than a politician.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/council-manager-system"},{"label":"Wikipedia — Council–manager government","url":"https://en.wikipedia.org/wiki/Council%E2%80%93manager_government"}]},
  {"kind":"governance","name":"Deliberative democracy","classed":"form of government","said":"Deliberative democracy or discursive democracy is a form of democracy in which deliberation is central to decision-making. It often shows characteristics of both consensus decision-making and majority rule. Deliberative democracy differs from traditional democratic theory in that authentic deliberation, not mere voting, is the primary source of legitimacy for the law that is produced. Deliberative democracy is related to consultative democracy, in which public consultation with citizens is central to democratic processes.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/deliberative-democracy"},{"label":"Wikipedia — Deliberative democracy","url":"https://en.wikipedia.org/wiki/Deliberative_democracy"}]},
  {"kind":"governance","name":"Dictatorship","classed":"form of government","said":"A dictatorship is a form of government which is characterized by a leader who holds absolute or near-absolute political power. Politics in a dictatorship are controlled by a dictator, and they are facilitated through an inner circle of elites that includes advisers, generals, and other high-ranking officials. The dictator maintains control by influencing and appeasing the inner circle and repressing any opposition, which may include rival political parties, armed resistance, or disloyal members of the dictator's inner circle.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/dictatorship"},{"label":"Wikipedia — Dictatorship","url":"https://en.wikipedia.org/wiki/Dictatorship"}]},
  {"kind":"governance","name":"Federation","classed":"form of government","said":"A federation (also called a federal state) is a union of partially self-governing provinces, states, or other regions under a federal government (federalism). In a federation, the self-governing status of the component units and the division of power between them and the central government are constitutionally entrenched and may not be altered unilaterally by either the central or constituent-unit authorities without following the constitutional amendment process.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/federation"},{"label":"Wikipedia — Federation","url":"https://en.wikipedia.org/wiki/Federation"}]},
  {"kind":"governance","name":"Feudalism","classed":"political system","said":"Feudalism, also known as the feudal system, was a combination of various customs and systems that flourished in medieval Europe from the 9th to 15th centuries. Broadly defined, it was a way of structuring society around relationships derived from the holding of land in exchange for service or labour. The classic definition, by François Louis Ganshof (1944), describes a set of reciprocal legal and military obligations of the warrior nobility and revolved around the key concepts of lords, vassals, and fiefs.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/feudalism"},{"label":"Wikipedia — Feudalism","url":"https://en.wikipedia.org/wiki/Feudalism"}]},
  {"kind":"governance","name":"Guided democracy","classed":"form of government","said":"Guided democracy, also called directed democracy and managed democracy, is a term used for some hybrid regimes that were or are formally democratic governments that function as de facto authoritarian governments. Guided democracies are legitimized by elections, but these elections do not change the state's policies, motives, and goals. In a guided democracy, the government controls elections so that citizens appear to exercise democratic rights without truly changing public policy. The state's continuous use of propaganda techniques prevents the electorate from having a significant impact on policy.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Guided-Democracy"},{"label":"Wikipedia — Guided democracy","url":"https://en.wikipedia.org/wiki/Guided_democracy"}]},
  {"kind":"governance","name":"Local government","classed":"form of government","said":"Local government is a generic term for the lowest tiers of governance or public administration within a particular sovereign state. A municipal council or local council is the legislative body of a municipality or local government area. Depending on the location and classification of the municipality it may be known as a city council, town council, town board, community council, borough council, rural council, village council, board of aldermen, or board of selectmen. Local governments typically constitute a subdivision of a higher-level political or administrative unit, such as a nation or state.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/local-government"},{"label":"Wikipedia — Local government","url":"https://en.wikipedia.org/wiki/Local_government"}]},
  {"kind":"governance","name":"Mayor–council government","classed":"form of government","said":"A mayor–council government is a system of local government in which a mayor who is directly elected by the voters acts as chief executive, while a separately elected city council constitutes the legislative body. It is one of the two most common forms of local government in the United States, and is the form most frequently adopted in large cities, although the other common form, council–manager government, is the local government form of more municipalities.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/mayor-and-council-system"},{"label":"Wikipedia — Mayor–council government","url":"https://en.wikipedia.org/wiki/Mayor%E2%80%93council_government"}]},
  {"kind":"governance","name":"Meritocracy","classed":"form of government","said":"Meritocracy (merit, from Latin mereō, and -cracy, from Ancient Greek κράτος kratos 'strength, power') is the notion of a political system in which economic goods or political power are vested in individual people based on ability and talent, rather than wealth or social class. Advancement in such a system is based on performance, as measured through examination or demonstrated achievement. Although the concept of meritocracy has existed for centuries, the first known use of the term was by sociologist Gordo Peruchi in the journal Socialist Commentary in 1956.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/meritocracy/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/meritocracy"},{"label":"Wikipedia — Meritocracy","url":"https://en.wikipedia.org/wiki/Meritocracy"}]},
  {"kind":"governance","name":"Military government","classed":"form of government","said":"A military government is any government that is administered by a military, whether or not this government is legal under the laws of the jurisdiction at issue or by an occupying power. It is usually administered by military personnel.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/military-government"},{"label":"Wikipedia — Military government","url":"https://en.wikipedia.org/wiki/Military_government"}]},
  {"kind":"governance","name":"Monarchy","classed":"form of government","said":"A monarchy is a hereditary arrangement in which the position of head of state, which may or may not be associated with political power, is legally passed on to a family member of the monarch, a head of state who reigns for life. While most monarchs gain their position based on various hereditary succession laws, they can occasionally gain their authority via election. Monarchies have historically been a common form of government. Nearly half of all independent states at the start of the 19th century were monarchies.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/monarchy"},{"label":"Wikipedia — Monarchy","url":"https://en.wikipedia.org/wiki/Monarchy"}]},
  {"kind":"governance","name":"Oligarchy","classed":"form of government","said":"Oligarchy (from Ancient Greek ὀλιγαρχία (oligarkhía) 'rule by few'; from ὀλίγος (olígos) 'few' and ἄρχω (árkhō) 'to rule, command') is a form of government in which power rests with a small number of people. Leaders of such regimes are often referred to as oligarchs, and generally are characterized by having titles of nobility or high amounts of wealth.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/oligarchy"},{"label":"Wikipedia — Oligarchy","url":"https://en.wikipedia.org/wiki/Oligarchy"}]},
  {"kind":"governance","name":"One-party state","classed":"form of government","said":"A one-party state, single-party state, one-party system or single-party system is a governance structure in which only a single political party controls the ruling system. In the one-party state, all opposition parties are either outlawed or have limited and controlled participation in elections. The expression \"de facto one-party\" is sometimes used to describe a dominant-party system that, unlike a one-party state, allows (at least nominally) multiparty elections, but the existing practices or balance of political power effectively prevent the opposition from winning power.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/single-party-system"},{"label":"Wikipedia — One-party state","url":"https://en.wikipedia.org/wiki/One-party_state"}]},
  {"kind":"governance","name":"Panchayati raj","classed":"political system","said":"The Panchayati raj is a political system originating from the Indian subcontinent, primarily found in India and neighbouring countries Pakistan, Bangladesh, Sri Lanka, and Nepal. It is one of the oldest systems of local government in the Indian subcontinent, with historical mentions dating back to around 250 CE. The word 'raj' means 'rule,' and panchayat' means 'assembly' (ayat) of 'five' (panch). Traditionally, panchayats consisted of wise and respected elders chosen and accepted by the local community. These assemblies resolved disputes between individuals and villages.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/panchayat-raj"},{"label":"Wikipedia — Panchayati raj","url":"https://en.wikipedia.org/wiki/Panchayati_raj"}]},
  {"kind":"governance","name":"Parliamentary system","classed":"form of government","said":"A parliamentary system is a form of government based on an executive branch dependent on the confidence of the legislative branch. In this system the head of government (chief executive) derives their democratic legitimacy from their ability to command the support (\"confidence\") of a majority of the parliament, to which they are held accountable. This head of government is usually, but not always, distinct from a ceremonial head of state.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/parliamentary-democracy"},{"label":"Wikipedia — Parliamentary system","url":"https://en.wikipedia.org/wiki/Parliamentary_system"}]},
  {"kind":"governance","name":"Patrimonialism","classed":"form of government","said":"Patrimonialism is a form of governance in which the ruler governs on the basis of personal loyalties which are derived from patron-client relations, personal allegiances, kin ties, and combinations thereof. Patrimonialism is closely related to corruption, opportunism, and machine politics. It can contribute to underdevelopment and weak state capacity. In contrast to many other systems of governance, the ruler does not derive legitimacy from personal charisma or a sense of mission, but primarily through the ability to dole out rewards and punishments.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/patrimonialism"},{"label":"Wikipedia — Patrimonialism","url":"https://en.wikipedia.org/wiki/Patrimonialism"}]},
  {"kind":"governance","name":"Pentarchy","classed":"form of government","said":"Pentarchy (from Ancient Greek Πενταρχία (Pentarchía), from πέντε (pénte) 'five' and ἄρχειν (archein) 'to rule') was a model of Church organization formulated in the laws of Emperor Justinian I (r. 527–565) of the Roman Empire. In this model, the Christian Church is governed by the heads (patriarchs) of the five major episcopal sees of the Roman Empire: Rome, Constantinople, Alexandria, Antioch and Jerusalem.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/pentarchy"},{"label":"Wikipedia — Pentarchy","url":"https://en.wikipedia.org/wiki/Pentarchy"}]},
  {"kind":"governance","name":"Polyarchy","classed":"form of government","said":"In political science, the term polyarchy, literally ”rule by many” (from Greek: \"poly\" many, \"arkhe\" rule) was used by Robert Dahl to describe a form of government in which power is invested in multiple people. It takes the form of neither a dictatorship nor a democracy. This form of government was first implemented in the United States and France and gradually adopted by other countries.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/polyarchy"},{"label":"Wikipedia — Polyarchy","url":"https://en.wikipedia.org/wiki/Polyarchy"}]},
  {"kind":"governance","name":"Polysynody","classed":"form of government","said":"Polysynody (from Greek πολυς numerous, several, and Greek συνοδος meeting, assembly) was an experimental system of government in use in Early Modern France between 1715 and 1718 and in which each minister (secretary of state) was replaced by a council. It was introduced early into the Regency of Philippe d'Orléans following the death of Louis XIV. The Polysynody was inspired by enlightenment ideals, however the system saw mixed successes but historians generally agree that the Polysynody didn't effectively alter either daily life nor the political culture of the Ancien régime.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Polysynodie"},{"label":"Wikipedia — Polysynody","url":"https://en.wikipedia.org/wiki/Polysynody"}]},
  {"kind":"governance","name":"Prebendalism","classed":"political system","said":"Prebendalism refers to political systems in which elected officials and government workers feel they have a right to a share of government revenues, and they use them to benefit supporters, co-religionists and members of their ethnic group.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/prebendal"},{"label":"Wikipedia — Prebendalism","url":"https://en.wikipedia.org/wiki/Prebendalism"}]},
  {"kind":"governance","name":"Principality","classed":"form of government","said":"A principality (or sometimes princedom) is a type of monarchical state or feudal territory ruled by a prince. Examples of principalities include the Principality of Monaco, the Grand Principality of Moscow, the Principality of Sheikhan, the Principality of Catalonia, and the Principality of Wales. The Principality of Antioch is another example of a principality, yet one created during the First Crusade which included parts of Anatolia (modern-day Turkey) and Syria. The principality was much smaller than the County of Edessa or the Kingdom of Jerusalem.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/principality"},{"label":"Wikipedia — Principality","url":"https://en.wikipedia.org/wiki/Principality"}]},
  {"kind":"governance","name":"Protectorate","classed":"form of government","said":"A protectorate, in the context of international relations, is a state or dependent territory that foregoes an independent foreign policy and often defence in favour of treaty with a protecting power, in order to ensure its defence against regional aggressors. It is a dependent territory that enjoys self government over most of its internal affairs, while still recognizing the suzerainty of a more powerful sovereign state without being a possession. In exchange, the protectorate accepts treaty obligations which bind it to the protecting power in foreign policy.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/protectorate-international-relations"},{"label":"Wikipedia — Protectorate","url":"https://en.wikipedia.org/wiki/Protectorate"}]},
  {"kind":"governance","name":"Regime","classed":"political system","said":"In politics, a regime (also spelled régime) is a system of norms, rules, and decision-making procedures. In the context of national politics, it typically refers to the system of political organization that determines access to public office, and the extent of power held by officials. Political scientists often categorize regimes as being democratic, autocratic, or hybrid. International regimes are sets of implicit or explicit principles, norms, rules, and decision-making procedures that international actors’ expectations converge around in a given area of international relations.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/regime"},{"label":"Wikipedia — Regime","url":"https://en.wikipedia.org/wiki/Regime"}]},
  {"kind":"governance","name":"Representative democracy","classed":"form of government","said":"Representative democracy, also known as indirect democracy or electoral democracy, is a type of democracy where elected delegates represent a group of people, in contrast to direct democracy. Nearly all modern Western-style democracies function as some type of representative democracy: for example, the United Kingdom (a unitary parliamentary constitutional monarchy), Germany (a federal parliamentary republic), France (a unitary semi-presidential republic), and the United States (a federal presidential republic).","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/representative-democracy"},{"label":"Wikipedia — Representative democracy","url":"https://en.wikipedia.org/wiki/Representative_democracy"}]},
  {"kind":"governance","name":"Republic","classed":"form of government","said":"A republic, based on the Latin phrase res publica ('public thing' or 'people's thing'), is a state in which political power rests with the public (people), typically through their representatives—in contrast to an absolute monarchy or a direct democracy. Although a republic is most often a single sovereign state, subnational state entities that have governments that are republican in nature may be referred to as republics. As of 2017, 159 of the world's 206 sovereign states use the word \"republic\" as part of their official names.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/republic-government"},{"label":"Wikipedia — Republic","url":"https://en.wikipedia.org/wiki/Republic"}]},
  {"kind":"governance","name":"Ritsuryō","classed":"political system","said":"Ritsuryō (律令; Japanese: [ɾi.tsɯ.ɾʲoː, ɾi.tsɯ.ɾei, ɾi.tsɯ.ɾeː]) is the historical legal system based on the philosophies of Confucianism and Chinese Legalism in Feudal Japan. The political system in accord to Ritsuryō is called \"Ritsuryō-sei\" (律令制). Kyaku (格) are amendments of Ritsuryō, Shiki (式) are enactments. Ritsuryō defines both a criminal code (律, Ritsu) and an administrative code (令, Ryō).","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/ritsuryo"},{"label":"Wikipedia — Ritsuryō","url":"https://en.wikipedia.org/wiki/Ritsury%C5%8D"}]},
  {"kind":"governance","name":"Saisei Itchi","classed":"form of government","said":"Saisei itchi (祭政一致) is a Japanese term meaning \"unity of worship and government\". Under a saisei itchi system, the political leader is also the religious leader. In Japan, unity of religion and rule can be traced back to the theocratic Yamato Kingship and Ryukyu Kingdom of ancient times where the proclamations of spiritual mediums had political authority. Saisei itchi is an inherent feature of the Shinto religion as the emperor is both leader of the country and priest to Japan's kami, though this aspect has not been focused on since the end of World War II.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/saisei-itchi"},{"label":"Wikipedia — Saisei Itchi","url":"https://en.wikipedia.org/wiki/Saisei_Itchi"}]},
  {"kind":"governance","name":"Signoria","classed":"form of government","said":"A signoria (Italian: [siɲɲoˈriːa]) was the governing authority in many of the Italian city-states during the Medieval and Renaissance periods. The word signoria comes from signore (Italian: [siɲˈɲoːre]), or \"lord\", an abstract noun meaning (roughly) \"government\", \"governing authority\", de facto \"sovereignty\", \"lordship\"; pl.: signorie.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/signoria"},{"label":"Wikipedia — Signoria","url":"https://en.wikipedia.org/wiki/Signoria"}]},
  {"kind":"governance","name":"Spoils system","classed":"political system","said":"In politics and government, a spoils system (also known as a patronage system) is a practice in which a political party, after winning an election, gives government jobs to its supporters, friends (cronyism), and relatives (nepotism) as a reward for working toward victory, and as an incentive to keep working for the party. It contrasts with a merit system, where offices are awarded or promoted based on a measure of merit, independent of political activity.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/spoils-system"},{"label":"Wikipedia — Spoils system","url":"https://en.wikipedia.org/wiki/Spoils_system"}]},
  {"kind":"governance","name":"State government","classed":"form of government","said":"A state government is the government that controls a subdivision of a country in a federal form of government, which shares political power with the federal or national government. A state government may have some level of political autonomy, or be subject to the direct control of the federal government. This relationship may be defined by a constitution. The reference to \"state\" denotes country subdivisions that are officially or widely known as \"states\", and should not be confused with a \"sovereign state\".","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/state-government"},{"label":"Wikipedia — State government","url":"https://en.wikipedia.org/wiki/State_government"}]},
  {"kind":"governance","name":"Tanistry","classed":"political system","said":"Tanistry was a system of inheritance practised by the Gaelic nobilities of Ireland, the Isle of Man, and parts of modern Scotland. It was distinctive in having an elected heir known as the tanist (Irish: tánaiste; Scottish Gaelic: tànaiste; Manx: tanishtey). This system was used to select the Chiefs of the Name (head of a clan) and the rulers of the various Gaelic kingdoms in Ireland and in Scotland. When the chief or king died they were immediately succeeded by the tanist, who had typically been elected years earlier. A new election was then held to select the next tanist.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/tanistry"},{"label":"Wikipedia — Tanistry","url":"https://en.wikipedia.org/wiki/Tanistry"}]},
  {"kind":"governance","name":"Theocracy","classed":"form of government","said":"Theocracy is a form of government in which one or more deities are recognized as supreme ruling authorities giving divine guidance to human intermediaries with executive, legislative or judicial power who manage the government's daily affairs.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/theocracy"},{"label":"Wikipedia — Theocracy","url":"https://en.wikipedia.org/wiki/Theocracy"}]},
  {"kind":"governance","name":"Theonomy","classed":"form of government","said":"Theonomy (from Greek θεός theos 'god' and νόμος nomos 'law') is a hypothetical Christian form of government in which divine law governs societies. Theonomists hold that societies should observe divine law, particularly the Old Testament’s judicial laws. The movement’s chief architects were Gary North, Greg Bahnsen, and R.J. Rushdoony. Theonomy presumes biblical Israel's Old Covenant judicial laws have not been abrogated, and therefore all civil governments must enforce them (including the specific penalties).","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/theonomy"},{"label":"Wikipedia — Theonomy","url":"https://en.wikipedia.org/wiki/Theonomy"}]},
  {"kind":"governance","name":"Triumvirate","classed":"form of government","said":"A triumvirate (Latin: triumvirātus) or a triarchy is a political institution ruled or dominated by three individuals, known as triumvirs (Latin: triumviri). The arrangement can be formal or informal. Though the three leaders in a triumvirate are notionally equal, the actual distribution of power may vary. Informally, the term \"triumvirate\" may be used for any association of three. Under the influence of the Soviet Union, the term troika (Russian: for \"group of three\") may be used for \"triumvirate\".","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/triumvirate"},{"label":"Wikipedia — Triumvirate","url":"https://en.wikipedia.org/wiki/Triumvirate"}]},
  {"kind":"governance","name":"Tyranny","classed":"form of government","said":"A tyrant (from Ancient Greek τύραννος (túrannos) 'absolute ruler') is an absolute ruler who is unrestrained by law, or one who has usurped a legitimate ruler's sovereignty. Often portrayed as cruel, tyrants may defend their positions by resorting to repressive means. The original Greek term meant an absolute sovereign who came to power without constitutional right, and the word had a neutral connotation during the Archaic and early Classical periods. A government run by a tyrant is usually called a tyranny.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/tyranny"},{"label":"Wikipedia — Tyranny","url":"https://en.wikipedia.org/wiki/Tyranny"}]},
  {"kind":"theory","name":"Agrarianism","classed":"political ideology","said":"Agrarianism is a social and political philosophy that advocates for rural development, a rural agricultural lifestyle, family farming, widespread property ownership, and political decentralization. Those who adhere to agrarianism tend to value traditional forms of local community over urban modernity. Agrarian political parties sometimes aim to support the rights and sustainability of small farmers and poor peasants against the wealthy, powerful and famous in society.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/agrarian-political-party"},{"label":"Wikipedia — Agrarianism","url":"https://en.wikipedia.org/wiki/Agrarianism"}]},
  {"kind":"theory","name":"Alt-right","classed":"political ideology","said":"The alt-right (abbreviated from alternative right) is a far-right and white nationalist movement. A largely online phenomenon, the alt-right originated in the United States during the late 2000s before increasing in popularity and establishing a presence in other countries during the mid-2010s. The term is ill-defined and has been used in different ways by academics, journalists, media commentators, and alt-right members themselves. In 2010, the American white nationalist Richard B. Spencer launched The Alternative Right webzine.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/alt-right"},{"label":"Wikipedia — Alt-right","url":"https://en.wikipedia.org/wiki/Alt-right"}]},
  {"kind":"theory","name":"Anarchism","classed":"political ideology","said":"Anarchism is a far-left political philosophy and movement that seeks to abolish all institutions that perpetuate authority, coercion, or hierarchy, primarily targeting the state, capitalism, and organised religion. Anarchism advocates for the replacement of these hierarchical social structures with stateless societies consisting of horizontal networks of voluntary associations that operate based on the principles of free association and reciprocity. Anarchism is described as being part of the libertarian wing of the socialist movement, broadly known as libertarian socialism.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/anarchism/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/anarchism"},{"label":"Wikipedia — Anarchism","url":"https://en.wikipedia.org/wiki/Anarchism"}]},
  {"kind":"theory","name":"Anarchist communism","classed":"political ideology","said":"Anarchist communism is an anarchist school of thought that advocates a form of communism where society is organized through horizontal networks of voluntary associations. It calls for the abolition of hierarchies, as well as private property but retention of personal property and collectively owned items, goods, and services. It supports common ownership of property and the free distribution of resources under the principle of \"from each according to his ability, to each according to his needs\". Anarchist communism was first formulated as such in the Italian section of the International Workingmen's Association.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/anarchist-communism"},{"label":"Wikipedia — Anarchist communism","url":"https://en.wikipedia.org/wiki/Anarchist_communism"}]},
  {"kind":"theory","name":"Anthropocentrism","classed":"political philosophy","said":"Anthropocentrism (from Ancient Greek ἄνθρωπος (ánthrōpos) 'human' and κέντρον (kéntron) 'center') is the belief that human beings are the central or most important entity on the planet. The term can be used interchangeably with humanocentrism, and some refer to the concept as human supremacy or human exceptionalism. From an anthropocentric perspective, humankind is seen as separate from nature and superior to it, and other entities (animals, plants, minerals, etc.) are viewed as resources for humans to use.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/anthropocentrism"},{"label":"Wikipedia — Anthropocentrism","url":"https://en.wikipedia.org/wiki/Anthropocentrism"}]},
  {"kind":"theory","name":"Authoritarianism","classed":"political ideology","said":"Authoritarianism is a political system characterized by the rejection of political plurality, the use of strong central power to preserve the political status quo, and reductions in democracy, separation of powers, civil liberties, and the rule of law. Authoritarian regimes may be either autocratic or oligarchic and may be based upon the rule of a party, the military, or the concentration of power in a single person. States that have a blurred boundary between democracy and authoritarianism have sometimes been characterized as \"hybrid democracies\", \"hybrid regimes\" or \"competitive authoritarian\" states.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/authoritarianism"},{"label":"Wikipedia — Authoritarianism","url":"https://en.wikipedia.org/wiki/Authoritarianism"}]},
  {"kind":"theory","name":"Bonapartism","classed":"political ideology","said":"Bonapartism (French: Bonapartisme [bɔnapaʁtism]) is the political ideology supervening from Napoleon Bonaparte and his legacy. The term is used in the narrow sense to refer to people who hoped to restore the House of Bonaparte and its style of government. In this sense, a Bonapartiste was a person who either actively participated in or advocated for imperial political factions in 19th-century France. Although Bonapartism emerged in 1814 with the first fall of Napoleon, it only developed doctrinal clarity and cohesion by the 1840s.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Bonapartist"},{"label":"Wikipedia — Bonapartism","url":"https://en.wikipedia.org/wiki/Bonapartism"}]},
  {"kind":"theory","name":"Carlism","classed":"political ideology","said":"Carlism (Basque: Karlismo; Catalan: Carlisme; Galician: Carlismo; Spanish: Carlismo) is a traditionalist and legitimist political movement in Spain aimed at establishing an alternative branch of the Bourbon dynasty, one descended from Don Carlos, Count of Molina (1788–1855), on the Spanish throne.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Carlism"},{"label":"Wikipedia — Carlism","url":"https://en.wikipedia.org/wiki/Carlism"}]},
  {"kind":"theory","name":"Chavismo","classed":"political ideology","said":"Chavismo (Spanish pronunciation: [tʃaˈβizmo]), also known in English as Chavism or Chavezism, is a left-wing populist political ideology based on the ideas, programs, and government style associated with Hugo Chávez, Nicolás Maduro, and Delcy Rodríguez. It combines elements of socialist patriotism, state nationalism, Bolivarianism, and Latin American integration. People who supported Hugo Chávez and Chavismo are known as Chavistas. The movement split into the Madurismo and anti-Madurismo factions in the 2010s.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/chavismo"},{"label":"Wikipedia — Chavismo","url":"https://en.wikipedia.org/wiki/Chavismo"}]},
  {"kind":"theory","name":"Christian democracy","classed":"political ideology","said":"Christian democracy is an ideology inspired by Christian social teaching to respond to the challenges of contemporary society and politics. Christian democracy has drawn mainly from Catholic social teaching and neo-scholasticism, as well as the Neo-Calvinist tradition within Christianity; it later gained ground with Lutherans and Pentecostals, among other denominational traditions of Christianity in various parts of the world.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Christian-democracy"},{"label":"Wikipedia — Christian democracy","url":"https://en.wikipedia.org/wiki/Christian_democracy"}]},
  {"kind":"theory","name":"Christian nationalism","classed":"political ideology","said":"Christian nationalism is an ideology that espouses a form of religious nationalism that focuses on promoting the Christian views of its followers in order to achieve prominence or dominance in political, cultural, and social life. In countries with a state church, Christian nationalists seek to preserve the status of a Christian state. Christian nationalism has been observed to overlap with antisemitism, racism and ethnonationalism.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Christian-nationalism"},{"label":"Wikipedia — Christian nationalism","url":"https://en.wikipedia.org/wiki/Christian_nationalism"}]},
  {"kind":"theory","name":"Christian right","classed":"political ideology","said":"The Christian right are Christian political factions characterized by their strong support of socially conservative and traditionalist policies. Christian conservatives seek to influence politics and public policy with their interpretation of the teachings of Christianity. In the United States, the Christian right (otherwise known as the New Christian Right or the Religious Right) is an informal coalition which was formed around a core of conservative Evangelical Protestants and conservative Roman Catholics.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Christian-Right"},{"label":"Wikipedia — Christian right","url":"https://en.wikipedia.org/wiki/Christian_right"}]},
  {"kind":"theory","name":"Christian socialism","classed":"political ideology","said":"Christian socialism is a religious and political philosophy that blends Christianity and socialism, endorsing socialist economics on the basis of the Bible and the teachings of Jesus. Many Christian socialists believe capitalism to be idolatrous and rooted in the sin of greed. Christian socialists identify the cause of social inequality to be the greed that they associate with capitalism. Christian socialism became a major movement in the United Kingdom beginning in the 19th century. Christians on the Left is one formal group, as well as a faction of the Labour Party.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Christian-Socialism"},{"label":"Wikipedia — Christian socialism","url":"https://en.wikipedia.org/wiki/Christian_socialism"}]},
  {"kind":"theory","name":"Classical liberalism","classed":"political ideology","said":"Classical liberalism (sometimes called English liberalism,) is a political philosophy and a branch of liberalism that advocates free market and laissez-faire economics and civil liberties under the rule of law, with special emphasis on individual autonomy, limited government, economic freedom, political freedom and freedom of speech. Classical liberalism, contrary to liberal branches like social liberalism or modern liberalism in the United States, looks more negatively on social policies, taxation and state involvement in the lives of individuals, and it advocates deregulation.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/classical-liberalism"},{"label":"Wikipedia — Classical liberalism","url":"https://en.wikipedia.org/wiki/Classical_liberalism"}]},
  {"kind":"theory","name":"Classical radicalism","classed":"political ideology","said":"Radicalism (from French radical) was a political movement representing the leftward flank of liberalism between the late 18th and early 20th century. Certain aspects of the movement were precursors to a wide variety of modern-day movements, ranging from laissez-faire to social liberalism, social democracy, civil libertarianism, and modern progressivism. This ideology is commonly referred to as \"radicalism\" but is sometimes referred to as radical liberalism, or classical radicalism, to distinguish it from radical politics.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/radicalism-philosophy"},{"label":"Wikipedia — Classical radicalism","url":"https://en.wikipedia.org/wiki/Classical_radicalism"}]},
  {"kind":"theory","name":"Communism","classed":"political ideology","said":"Communism (from Latin communis 'common, universal') is a political and economic ideology whose goal is the creation of a communist society, a socioeconomic classless order centered on common ownership of the means of production, distribution, and exchange that allocates products in society based on need. A communist society entails the absence of private property and social classes, and ultimately money and the state. Communists often seek a voluntary state of self-governance but disagree on the means to this end.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/communism"},{"label":"Wikipedia — Communism","url":"https://en.wikipedia.org/wiki/Communism"}]},
  {"kind":"theory","name":"Communitarianism","classed":"political ideology","said":"Communitarianism is a philosophy that emphasizes the connection between the individual and the community. Its overriding philosophy is based on the belief that a person's social identity and personality are largely moulded by community relationships, with a smaller degree of development being placed on individualism. Although the community might be a family, communitarianism usually is understood, in the wider, philosophical sense, as a collection of interactions, among a community of people in a given place (geographical location), or among a community who share an interest or who share a history.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/communitarianism/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/communitarianism"},{"label":"Wikipedia — Communitarianism","url":"https://en.wikipedia.org/wiki/Communitarianism"}]},
  {"kind":"theory","name":"Conservatism","classed":"political ideology","said":"Conservatism is a cultural, social, and political philosophy and ideology that seeks to promote and preserve traditional institutions, customs, and values. The central tenets of conservatism may vary in relation to the culture and civilization in which it appears. In Western culture, depending on the particular nation and the particular time period, conservatives seek to promote and preserve a range of institutions, such as the nuclear family, organized religion, the military, the nation-state, constitution, property rights, rule of law, aristocracy, and monarchy.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/conservatism/"},{"label":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/polphil/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/conservatism"},{"label":"Wikipedia — Conservatism","url":"https://en.wikipedia.org/wiki/Conservatism"}]},
  {"kind":"theory","name":"Constitutionalism","classed":"political ideology","said":"Constitutionalism is \"a compound of ideas, attitudes, and patterns of behavior elaborating the principle that the authority of government derives from and is limited by a body of fundamental law\". Political organizations are constitutional to the extent that they \"contain institutionalized mechanisms of power control for the protection of the interests and liberties of the citizenry, including those that may be in the minority\".","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/constitutionalism/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/constitutional-government"},{"label":"Wikipedia — Constitutionalism","url":"https://en.wikipedia.org/wiki/Constitutionalism"}]},
  {"kind":"theory","name":"Corporatism","classed":"political ideology","said":"Corporatism is a political ideology and political system of interest representation and policymaking whereby corporate groups, such as agricultural, labour, military, business, scientific, or guild associations, come together and negotiate contracts or policy (collective bargaining) on the basis of their common interests. The term is derived from the Latin corpus, or \"body\". Corporatism does not refer to a political system dominated by large business interests, even though the latter are commonly called \"corporations\" in modern American vernacular and legal parlance.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/corporatism"},{"label":"Wikipedia — Corporatism","url":"https://en.wikipedia.org/wiki/Corporatism"}]},
  {"kind":"theory","name":"Decentralization","classed":"political ideology","said":"Decentralization is the process by which the activities of an organization, particularly those related to planning and decision-making, are distributed or delegated away from a central, authoritative location or group and given to smaller factions within it. Concepts of decentralization have been applied to group dynamics and management science in private businesses and organizations, political science, law and public administration, technology, economics and money.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/devolution-government-and-politics"},{"label":"Wikipedia — Decentralization","url":"https://en.wikipedia.org/wiki/Decentralization"}]},
  {"kind":"theory","name":"Democracy","classed":"political ideology","said":"Democracy is a form of government in which political power is vested in the people of a certain state. Under a narrow definition of democracy, rulers are elected through competitive elections, while broader definitions also link democracy to guarantees of civil liberties and human rights. In a direct democracy, the people have the primary authority to deliberate and decide legislation. In a representative democracy, the people elect governing officials to do so.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/democracy/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/democracy"},{"label":"Wikipedia — Democracy","url":"https://en.wikipedia.org/wiki/Democracy"}]},
  {"kind":"theory","name":"Democratic centralism","classed":"political ideology","said":"Democratic centralism is a Leninist principle which combines open, internal debate on policies with strict and uniform adherence once debated and adopted. It is adopted by communist states and their governing communist parties. It has also been adopted as the organizational principle of other communist parties, \"transmission belt\" organizations, and other units operating within communist state systems, as well as by some non-communist organizations.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/democratic-centralism"},{"label":"Wikipedia — Democratic centralism","url":"https://en.wikipedia.org/wiki/Democratic_centralism"}]},
  {"kind":"theory","name":"Democratic socialism","classed":"political ideology","said":"Democratic socialism is a set of left-wing political philosophies that supports political democracy and some form of a socially owned economy, with a particular emphasis on economic democracy, workplace democracy, and workers' self-management within a market socialist, decentralised planned, or democratic centrally planned socialist economy. Democratic socialists argue that capitalism is inherently incompatible with the values of freedom, equality, and solidarity and that these ideals can only be achieved through the realisation of a socialist society.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/money/democratic-socialism"},{"label":"Wikipedia — Democratic socialism","url":"https://en.wikipedia.org/wiki/Democratic_socialism"}]},
  {"kind":"theory","name":"Direct democracy","classed":"political ideology","said":"Direct democracy or pure democracy is a form of democracy in which the electorate directly decides on policy initiatives, without elected representatives as proxies, as opposed to the representative democracy model which occurs in the majority of established democracies. The theory and practice of direct democracy and participation as its common characteristic constituted the core of the work of many theorists, philosophers, politicians, and social critics, such as Jean-Jacques Rousseau, John Stuart Mill, and G.D.H. Cole.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/direct-democracy"},{"label":"Wikipedia — Direct democracy","url":"https://en.wikipedia.org/wiki/Direct_democracy"}]},
  {"kind":"theory","name":"Dirigisme","classed":"political ideology","said":"Dirigisme (French: [diʁiʒism]), or dirigism (from French diriger 'to direct'), refers to an economic system in which the state takes an active and directive role in shaping and guiding the economy, rather than limiting itself to a purely regulatory or hands-off approach within a market economy. As an economic doctrine, dirigisme stands in contrast to laissez-faire, highlighting the constructive role of market intervention in addressing inefficiencies and market failures.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/dirigisme"},{"label":"Wikipedia — Dirigisme","url":"https://en.wikipedia.org/wiki/Dirigisme"}]},
  {"kind":"theory","name":"Dominion theology","classed":"political ideology","said":"Dominion theology, also known as dominionism, is a group of Protestant Christian political ideologies that seek to institute a nation governed by Christians based on their understandings of biblical law. Prominent adherents of those ideologies include Calvinist Christian reconstructionism, Charismatic and Pentecostal Kingdom Now theology, and the New Apostolic Reformation. Extents of rule and ways of acquiring governing authority are varied. For example, dominion theology can include theonomy but does not necessarily involve advocacy of adherence to the Mosaic Law as the basis of government.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/dominion-theory"},{"label":"Wikipedia — Dominion theology","url":"https://en.wikipedia.org/wiki/Dominion_theology"}]},
  {"kind":"theory","name":"Ecocentrism","classed":"political philosophy","said":"Ecocentrism (; from Greek: οἶκος /ˈoi.kos/ oikos, 'house' and κέντρον /ˈken.tron/ kentron, 'center') is a term used by environmental philosophers and ecologists to denote a nature-centered, as opposed to human-centered (i.e., anthropocentric), system of values. The justification for ecocentrism usually consists in an ontological belief and subsequent ethical claim. The ontological belief denies that there are any existential divisions between human and non-human nature sufficient to claim that humans are either (a) the sole bearers of intrinsic value or (b) possess greater intrinsic value than non-human nature.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/ecocentrism"},{"label":"Wikipedia — Ecocentrism","url":"https://en.wikipedia.org/wiki/Ecocentrism"}]},
  {"kind":"theory","name":"Egalitarianism","classed":"political ideology","said":"Egalitarianism (from French égal 'equal'; also equalitarianism) is a school of thought within political philosophy that builds on the concept of social equality, prioritizing it for all people. Egalitarian doctrines are generally characterized by the idea that all humans are equal in fundamental worth or moral status. As such, all people should be accorded equal rights and treatment under the law.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/egalitarianism/"},{"label":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/egalitar/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/egalitarianism"},{"label":"Wikipedia — Egalitarianism","url":"https://en.wikipedia.org/wiki/Egalitarianism"}]},
  {"kind":"theory","name":"Environmentalism","classed":"political ideology","said":"Environmentalism is a broad philosophy, ideology, and social movement about supporting life, habitats, and surroundings. While environmentalism focuses on the environmental and nature-related aspects of green ideology and politics, ecologism combines the ideology of social ecology and environmentalism. Ecologism is a term more commonly used in continental European languages, while environmentalism is more commonly used in English, but the words have slightly different connotations.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/environmentalism"},{"label":"Wikipedia — Environmentalism","url":"https://en.wikipedia.org/wiki/Environmentalism"}]},
  {"kind":"theory","name":"Eurocommunism","classed":"political ideology","said":"Eurocommunism was a trend in the 1970s and 1980s within various Western European communist parties, which said they had developed a theory and practice of social transformation more relevant for Western Europe. During the Cold War, they sought to reject the influence of the Soviet Union and its Communist Party. The trend was prominent in Italy, Spain, and, to a lesser extent, France. It is commonly considered to have been prompted by the Prague Spring.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Eurocommunism"},{"label":"Wikipedia — Eurocommunism","url":"https://en.wikipedia.org/wiki/Eurocommunism"}]},
  {"kind":"theory","name":"Euroscepticism","classed":"political ideology","said":"Euroscepticism, also spelled as Euroskepticism or EU-scepticism, is a political position involving criticism of the European Union (EU) and European integration. It ranges from those who oppose some EU institutions and policies and seek reform (Eurorealism, Eurocritical, or soft Euroscepticism), to those who oppose EU membership and see the EU as unreformable (anti-European Unionism, anti-EUism, or hard Euroscepticism). The opposite of Euroscepticism is known as pro-Europeanism.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Euroskepticism"},{"label":"Wikipedia — Euroscepticism","url":"https://en.wikipedia.org/wiki/Euroscepticism"}]},
  {"kind":"theory","name":"Fascism","classed":"political ideology","said":"Fascism ( FASH-iz-əm) is a far-right, authoritarian, and ultranationalist political ideology and movement that rose to prominence in early-20th-century Europe. Fascism is characterized by support for a dictatorial leader, centralized autocracy, militarism, forcible suppression of opposition, belief in a natural social hierarchy, subordination of individual interests for the perceived interest of the nation or race, and strong regimentation of society and the economy. Opposed to communism, democracy, liberalism, pluralism, and socialism, fascism is at the far-right end of the traditional left–right spectrum.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/fascism"},{"label":"Wikipedia — Fascism","url":"https://en.wikipedia.org/wiki/Fascism"}]},
  {"kind":"theory","name":"Feminism","classed":"political ideology","said":"Feminism is a range of socio-political movements and ideologies that aim to define and establish the political, economic, personal, and social equality of the sexes. Feminism holds the position that modern societies are patriarchal—they prioritize the male point of view—and that women are treated unjustly in these societies. Efforts to change this include fighting against gender stereotypes, breaking down traditional gender roles, and improving educational, professional, and interpersonal opportunities and outcomes for women. A person who advocates for feminism is known as a feminist.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/feminism-topics/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/feminism"},{"label":"Wikipedia — Feminism","url":"https://en.wikipedia.org/wiki/Feminism"}]},
  {"kind":"theory","name":"Fourierism","classed":"political ideology","said":"Fourierism () is the systematic set of economic, political, and social beliefs first espoused by French intellectual Charles Fourier (1772–1837). It is based on a belief in the inevitability of communal associations of people who work and live together as part of the human future. Fourier's supporters called his doctrines associationism. Political contemporaries and subsequent scholarship have identified Fourier's set of ideas as a form of utopian socialism.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Fourierism"},{"label":"Wikipedia — Fourierism","url":"https://en.wikipedia.org/wiki/Fourierism"}]},
  {"kind":"theory","name":"Hindutva","classed":"political ideology","said":"Hindutva is a Hindu nationalist political ideology. Formulated by Vinayak Damodar Savarkar in Essentials of Hindutva in 1923, it is primarily espoused by the Rashtriya Swayamsevak Sangh (RSS), the Vishva Hindu Parishad (VHP), the ruling Bharatiya Janata Party (BJP), and other organisations collectively known as the Sangh Parivar. Borrowing ideas and concepts from European fascism, the Hindutva movement engaged in a mutually beneficial relationship with Fascist Italy and Nazi Germany during the interwar period and the Second World War.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Hindutva"},{"label":"Wikipedia — Hindutva","url":"https://en.wikipedia.org/wiki/Hindutva"}]},
  {"kind":"theory","name":"Indigenismo","classed":"political ideology","said":"Indigenismo (Spanish: [indixeˈnismo]) is a political ideology in several Latin American countries which emphasizes the relationship between the nation state and Indigenous nations and Indigenous peoples. In some contemporary uses, it refers to the pursuit of greater social and political inclusion for Indigenous peoples in Latin America, whether through nation-wide reforms or region-wide alliances.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/Indigenismo"},{"label":"Wikipedia — Indigenismo","url":"https://en.wikipedia.org/wiki/Indigenismo"}]},
  {"kind":"theory","name":"Individualism","classed":"political philosophy","said":"Individualism is the moral stance, political philosophy, ideology, and social outlook that emphasizes the worth or central role of the individual. Individualists promote realizing one's goals and desires, valuing independence and self-reliance, and advocating that the interests of the individual should take precedence over the state or a social group, while opposing external interference with one's interests by society or institutions such as the government.","sources":[{"label":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/ind-chin/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/art/Individualists"},{"label":"Wikipedia — Individualism","url":"https://en.wikipedia.org/wiki/Individualism"}]},
  {"kind":"theory","name":"Integral nationalism","classed":"political ideology","said":"Integral nationalism (French: nationalisme intégral) is a type of nationalism that originated in 19th-century France, was theorized by Charles Maurras and mainly expressed in the ultra-royalist circles of the Action Française. Integral nationalism holds the nation as the highest absolute value to which all individual, class, and humanitarian interests are subordinated, with willpower prioritised over reason. The doctrine is also called Maurrassisme.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/integral-nationalism"},{"label":"Wikipedia — Integral nationalism","url":"https://en.wikipedia.org/wiki/Integral_nationalism"}]},
  {"kind":"theory","name":"Integralism","classed":"political ideology","said":"Integralism, integrationism or integrism (French: intégrisme) is an interpretation of Catholic social teaching that argues the principle that the Catholic faith should be the basis of public law and public policy within civil society, wherever the preponderance of Catholics within that society makes this possible. Integralism opposes pluralism, seeking the Catholic faith to be dominant in civil and religious matters.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Integralist-Portuguese-history"},{"label":"Wikipedia — Integralism","url":"https://en.wikipedia.org/wiki/Integralism"}]},
  {"kind":"theory","name":"Internationalism (politics)","classed":"political ideology","said":"Internationalism is a political principle that advocates greater political or economic cooperation among states and nations. It is associated with other political movements and ideologies, but can also reflect a doctrine, belief system, or movement in itself. Supporters of internationalism are known as internationalists and generally believe that humans should unite across national, political, cultural, racial, or class boundaries to advance their common interests, or that governments should cooperate because their mutual long-term interests are of greater importance than their short-term disputes.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/internationalism"},{"label":"Wikipedia — Internationalism (politics)","url":"https://en.wikipedia.org/wiki/Internationalism_(politics)"}]},
  {"kind":"theory","name":"Isolationism","classed":"political ideology","said":"Isolationism is a political philosophy advocating a foreign policy that opposes involvement in the political affairs, and especially the wars, of other countries. Thus, isolationism fundamentally advocates neutrality and opposes entanglement in military alliances and mutual defense pacts. In its purest form, isolationism opposes all commitments to foreign countries, including treaties and trade agreements. In the political science lexicon, there is also the term of \"non-interventionism\", which is sometimes improperly used to replace the concept of \"isolationism\".","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/isolationism-foreign-policy"},{"label":"Wikipedia — Isolationism","url":"https://en.wikipedia.org/wiki/Isolationism"}]},
  {"kind":"theory","name":"Juche","classed":"political ideology","said":"Juche, officially the Juche idea, is a name of the official ideology of North Korea and its ruling Workers' Party of Korea (WPK). In the narrow sense, it is the philosophical component of the North Korean official ideology, also known as Kimilsungism–Kimjongilism, which emphasizes human independence, creativity, and consciousness as a motive force. North Korean sources attribute its conceptualization to Kim Il Sung, the country's founder and first leader.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/juche"},{"label":"Wikipedia — Juche","url":"https://en.wikipedia.org/wiki/Juche"}]},
  {"kind":"theory","name":"Judicial restraint","classed":"political ideology","said":"Judicial restraint is a judicial interpretation that recommends favoring the status quo in judicial activities and is the opposite of judicial activism. Aspects of judicial restraint include the principle of stare decisis (that new decisions should be consistent with previous decisions); a conservative approach to standing (locus standi) and a reluctance to grant certiorari; and a tendency to deliver narrowly tailored verdicts, avoiding \"unnecessary resolution of broad questions.\" Judicial restraint may lead a court to avoid hearing a case in the first place.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/judicial-restraint"},{"label":"Wikipedia — Judicial restraint","url":"https://en.wikipedia.org/wiki/Judicial_restraint"}]},
  {"kind":"theory","name":"Leninism","classed":"political ideology","said":"Leninism (Russian: Ленинизм, Leninizm) is a political ideology developed by Russian Marxist revolutionary Vladimir Lenin that proposes the establishment of the dictatorship of the proletariat led by a revolutionary vanguard party as the political prelude to the establishment of communism. Lenin's ideological contributions to the Marxist ideology relate to his theories on the party, imperialism, the state, and revolution.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Leninism"},{"label":"Wikipedia — Leninism","url":"https://en.wikipedia.org/wiki/Leninism"}]},
  {"kind":"theory","name":"Liberal democracy","classed":"political philosophy","said":"Liberal democracy, also called Western-style democracy, is a form of government that combines the organization of a democracy with ideas of liberal political philosophy.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/liberal-democracy"},{"label":"Wikipedia — Liberal democracy","url":"https://en.wikipedia.org/wiki/Liberal_democracy"}]},
  {"kind":"theory","name":"Liberal feminism","classed":"political ideology","said":"Liberal feminism is a main branch of feminism defined by its focus on achieving gender equality through political and legal reform within the framework of liberal democracy and informed by a human rights perspective. It is often considered culturally progressive and economically center-right to center-left.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/feminism-liberal/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/liberal-feminism"},{"label":"Wikipedia — Liberal feminism","url":"https://en.wikipedia.org/wiki/Liberal_feminism"}]},
  {"kind":"theory","name":"Liberal internationalism","classed":"political ideology","said":"Liberal internationalism is a foreign policy doctrine that supports international institutions, open markets, cooperative security, and liberal democracy. At its core, it holds that states should participate in international institutions that uphold rules-based norms, promote liberal democracy, and facilitate cooperation on transnational problems (such as environmental problems, arms control, and public health).","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/liberal-internationalism"},{"label":"Wikipedia — Liberal internationalism","url":"https://en.wikipedia.org/wiki/Liberal_internationalism"}]},
  {"kind":"theory","name":"Liberalism","classed":"political ideology","said":"Liberalism is a political and moral philosophy based on the rights of the individual, liberty, consent of the governed, political equality, right to private property, and equality before the law. Different liberals espouse various and sometimes conflicting views depending on their understanding of these principles but generally support liberal democracy, private property, market economies, individual rights (including civil rights and human rights), secularism, rule of law, economic and political freedom, freedom of speech, freedom of the press, freedom of assembly, and freedom of religion.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/liberalism/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/liberalism"},{"label":"Wikipedia — Liberalism","url":"https://en.wikipedia.org/wiki/Liberalism"}]},
  {"kind":"theory","name":"Macedonian nationalism","classed":"political ideology","said":"Macedonian nationalism (Macedonian: македонски национализам, pronounced [makɛdonski nat͡sionalizam]), sometimes referred to as Macedonianism and Macedonism, is a general grouping of nationalist ideas and concepts among ethnic Macedonians that were first formed in the second half of the 19th century among separatists seeking the autonomy of the region of Macedonia from the Ottoman Empire. The movement began as a cultural reaction against Greek, Turkish, and Patriarchist influences, and was fueled by the broader political and social changes within the Ottoman Empire.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Macedonianism"},{"label":"Wikipedia — Macedonian nationalism","url":"https://en.wikipedia.org/wiki/Macedonian_nationalism"}]},
  {"kind":"theory","name":"Majoritarianism","classed":"political ideology","said":"Majoritarianism is a political philosophy or ideology with an agenda asserting that a majority, whether based on a religion, language, social class, or other category of the population, is entitled to a certain degree of primacy in society, and has the right to make decisions that affect the society. This traditional view has come under growing criticism, and liberal democracies have increasingly included constraints on what the parliamentary majority can do, in order to protect citizens' fundamental rights.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/majoritarianism"},{"label":"Wikipedia — Majoritarianism","url":"https://en.wikipedia.org/wiki/Majoritarianism"}]},
  {"kind":"theory","name":"Maoism","classed":"political ideology","said":"Maoism, officially Mao Zedong Thought, is a variety of Marxism–Leninism that Mao Zedong developed while trying to realise a socialist revolution in the agricultural, pre-industrial society of the Republic of China and later the People's Republic of China. A difference between Maoism and traditional Marxism–Leninism is that a united front of progressive forces in class society would lead the revolutionary vanguard in pre-industrial societies rather than communist revolutionaries alone.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Maoism"},{"label":"Wikipedia — Maoism","url":"https://en.wikipedia.org/wiki/Maoism"}]},
  {"kind":"theory","name":"Marxism","classed":"political ideology","said":"Marxism is a political philosophy and method of socioeconomic analysis that uses a dialectical materialist interpretation of historical development, known as historical materialism, to understand class relations and social conflict. Originating in the works of 19th-century German philosophers Karl Marx and Friedrich Engels, the Marxist approach views class struggle as the central driving force of historical change. Marxist analysis views a society's economic mode of production as the foundation of its social, political, and intellectual life, a concept known as the base and superstructure model.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Marxism"},{"label":"Wikipedia — Marxism","url":"https://en.wikipedia.org/wiki/Marxism"}]},
  {"kind":"theory","name":"Militarism","classed":"political ideology","said":"Militarism is the belief or the desire of a government or a people that a state should maintain a strong military capability and to use it aggressively to expand national interests and/or values. It may also imply the glorification of the military and of the ideals of a professional military class and the \"predominance of the armed forces in the administration or policy of the state.\"","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/militarism"},{"label":"Wikipedia — Militarism","url":"https://en.wikipedia.org/wiki/Militarism"}]},
  {"kind":"theory","name":"Mutualism (economic theory)","classed":"political ideology","said":"Mutualism is an anarchist school of thought and economic theory that advocates for workers' control of the means of production, a free market made up of individual artisans, sole proprietorships and workers' cooperatives, and occupation and use property rights. As proponents of the labour theory of value and labour theory of property, mutualists oppose all forms of economic rent, profit and non-nominal interest, which they see as relying on the exploitation of labour. Mutualists seek to construct an economy without capital accumulation or concentration of land ownership.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Mutualists"},{"label":"Wikipedia — Mutualism (economic theory)","url":"https://en.wikipedia.org/wiki/Mutualism_(economic_theory)"}]},
  {"kind":"theory","name":"National communism","classed":"political ideology","said":"National communism is a term describing various forms in which Marxism–Leninism and communism has been adopted and/or implemented by leaders in different countries using aspects of nationalism or national identity to form a policy independent from communist internationalism. National communism has been used to describe movements and governments that have sought to form a distinctly unique variant of communism based upon distinct national characteristics and circumstances, rather than following policies set by other communist states, such as the Soviet Union.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/National-Communism"},{"label":"Wikipedia — National communism","url":"https://en.wikipedia.org/wiki/National_communism"}]},
  {"kind":"theory","name":"Nationalism","classed":"political ideology","said":"Nationalism is an ideology or movement that holds that the nation should be congruent with the state. As a movement, it presupposes the existence and tends to promote the interests of a particular nation, especially with the aim of gaining and maintaining its sovereignty (self-determination) over its perceived homeland to create a nation-state. It holds that the nation should govern itself, free from outside interference (self-governance), that a nation is a natural and ideal basis for a polity, and that the nation is the only rightful source of political power.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/nationalism/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/nationalism"},{"label":"Wikipedia — Nationalism","url":"https://en.wikipedia.org/wiki/Nationalism"}]},
  {"kind":"theory","name":"Nativism (politics)","classed":"political ideology","said":"Nativism is a political policy of promoting or protecting the interests of native-born or indigenous people over those of immigrants, including opposition to immigration.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/nativism"},{"label":"Wikipedia — Nativism (politics)","url":"https://en.wikipedia.org/wiki/Nativism_(politics)"}]},
  {"kind":"theory","name":"Nazism","classed":"political ideology","said":"Nazism, formally named National Socialism, is the far-right, ultranationalist, racist and totalitarian ideology associated with Adolf Hitler and the Nazi Party (NSDAP). It emerged in Germany during Hitler's rise to power and was frequently called Hitlerism. Nazism is a form of fascism that emphasizes pseudo-scientific theories of racial hierarchy which identify ethnic Germans and Nordic-Aryans as a master race. The term \"neo-Nazism\" is applied to far-right groups formed after World War II with a similar ideology. Nazism opposes liberal democracy and the parliamentary system.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/National-Socialism"},{"label":"Wikipedia — Nazism","url":"https://en.wikipedia.org/wiki/Nazism"}]},
  {"kind":"theory","name":"Neo-fascism","classed":"political ideology","said":"Neo-fascism is a post-World War II far-right ideology which includes significant elements of fascism. Neo-fascism usually includes ultranationalism, ultraconservatism, racial supremacy, right-wing populism, authoritarianism, nativism, xenophobia, and anti-immigration sentiment, as well as opposition to social democracy, parliamentarianism, Marxism, communism, socialism, liberalism, neoliberalism, and liberal democracy.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/neofascism"},{"label":"Wikipedia — Neo-fascism","url":"https://en.wikipedia.org/wiki/Neo-fascism"}]},
  {"kind":"theory","name":"Neo-Marxism","classed":"political ideology","said":"Neo-Marxism is a collection of Marxist schools of thought that originated from 20th-century approaches to amend or extend Marxism and Marxist theory, typically by incorporating elements from other intellectual traditions such as critical theory, psychoanalysis, or existentialism. Neo-Marxism comes under the broader framework of the New Left. In a sociological sense, neo-Marxism adds Max Weber's broader understanding of social inequality, such as status and power, to Marxist philosophy.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/neo-Marxism"},{"label":"Wikipedia — Neo-Marxism","url":"https://en.wikipedia.org/wiki/Neo-Marxism"}]},
  {"kind":"theory","name":"Neoconservatism","classed":"political ideology","said":"Neoconservatism (colloquially neocon) is a political movement that combines features of traditional political and social conservatism with individualism and a qualified endorsement of free markets along with the assertive promotion of democracy and national interest, primarily through military means. It began in the United States during the 1970s among liberal hawks who became disenchanted with the Democratic Party along with the growing New Left and 1960s counterculture.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/neoconservatism"},{"label":"Wikipedia — Neoconservatism","url":"https://en.wikipedia.org/wiki/Neoconservatism"}]},
  {"kind":"theory","name":"Neoliberalism","classed":"political ideology","said":"Neoliberalism is a political and economic ideology that advocates for free-market capitalism, and that became dominant in policy-making from the late 20th century onward. The term has multiple, competing definitions, and is most often used pejoratively. In scholarly use, the term is often left undefined or used to describe a multitude of phenomena. However, it is primarily employed to delineate the societal transformation resulting from market-based reforms.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/neoliberalism/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/neoliberalism"},{"label":"Wikipedia — Neoliberalism","url":"https://en.wikipedia.org/wiki/Neoliberalism"}]},
  {"kind":"theory","name":"New liberalism (ideology)","classed":"political ideology","said":"New liberalism is a variant of social liberalism that emerged in Europe at the end of the 19th century. It began in England driven mainly by the politician and sociologist Leonard Trelawny Hobhouse and theorized in his book Liberalism (1920). It had reception within the Liberal Party of the United Kingdom, giving a rapprochement between it and the Labour Party on social issues.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/new-liberalism"},{"label":"Wikipedia — New liberalism (ideology)","url":"https://en.wikipedia.org/wiki/New_liberalism_(ideology)"}]},
  {"kind":"theory","name":"New Nationalism (Theodore Roosevelt)","classed":"political philosophy","said":"The New Nationalism was a policy platform first proposed by former President of the United States Theodore Roosevelt in a speech in Osawatomie, Kansas, on August 31, 1910. The progressive nationalist policies outlined in the speech would form the basis for his campaign for a third term as president in the 1912 election, first as a candidate for the Republican Party nomination and then as a Progressive.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/New-Nationalism"},{"label":"Wikipedia — New Nationalism (Theodore Roosevelt)","url":"https://en.wikipedia.org/wiki/New_Nationalism_(Theodore_Roosevelt)"}]},
  {"kind":"theory","name":"One-state solution","classed":"political ideology","said":"The one-state solution is a proposed approach to the Israeli–Palestinian peace process that envisions a single state within the boundaries of the former Mandatory Palestine. The term one-state reality refers to the view that the current situation in the Israeli–Palestinian conflict amounts to a single de facto political space. The one-state solution is sometimes described as a bi-national state, reflecting the idea that it could provide self-determination to Israelis and Palestinians within a shared state.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/one-state-solution"},{"label":"Wikipedia — One-state solution","url":"https://en.wikipedia.org/wiki/One-state_solution"}]},
  {"kind":"theory","name":"Open society","classed":"political ideology","said":"Open society (French: société ouverte) is a term coined by French philosopher Henri Bergson in 1932, and describes a dynamic system inclined to moral universalism. Bergson contrasted an open society with what he called a closed society, a closed system of law, morality or religion. Bergson suggests that if all traces of civilization were to disappear, the instincts of the closed society for including or excluding others would remain. The idea of an open society was further developed during World War II by the Austrian-born Jewish philosopher Karl Popper.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/open-society-sociology"},{"label":"Wikipedia — Open society","url":"https://en.wikipedia.org/wiki/Open_society"}]},
  {"kind":"theory","name":"Paleoconservatism","classed":"political ideology","said":"Paleoconservatism is a strain of conservatism in the United States that stresses American nationalism, Christian ethics, traditionalist conservatism, localism and non-interventionism. Paleoconservatism's concerns overlap with those of the Old Right (which opposed the New Deal in the 1930s and 1940s) as well as with paleolibertarianism.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/paleoconservatism"},{"label":"Wikipedia — Paleoconservatism","url":"https://en.wikipedia.org/wiki/Paleoconservatism"}]},
  {"kind":"theory","name":"Pan-Africanism","classed":"political ideology","said":"Pan-Africanism is a movement that aims to encourage and strengthen bonds of solidarity between all indigenous peoples of Africa along with all peoples of African descent. Based on a common goal dating back to the Atlantic slave trade, the Trans-Saharan slave trade, the Indian Ocean slave trade, the Red Sea slave trade, slavery in the Cape Colony, Inboekstelsel, slavery in Mauritius, and the Khoikhoi-Dutch Wars, the belief extends beyond continental Africans with a substantial support base among the African diaspora in the Americas and Europe.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Pan-Africanism"},{"label":"Wikipedia — Pan-Africanism","url":"https://en.wikipedia.org/wiki/Pan-Africanism"}]},
  {"kind":"theory","name":"Pan-Arabism","classed":"political ideology","said":"Pan-Arabism (Arabic: الوحدة العربية, romanized: al-waḥda al-ʿarabiyyah, lit. 'Arab unity') is a pan-nationalist ideology that espouses the unification of all Arab people in a single nation-state, consisting of all Arab countries of West Asia and North Africa from the Atlantic Ocean to the Arabian Sea, which is referred to as the Arab world. It is closely connected to Arab nationalism, which asserts the view that the Arabs constitute a single nation.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Pan-Arabism"},{"label":"Wikipedia — Pan-Arabism","url":"https://en.wikipedia.org/wiki/Pan-Arabism"}]},
  {"kind":"theory","name":"Pan-Islamism","classed":"political ideology","said":"Pan-Islamism (Arabic: الوحدة الإسلامية, romanized: al-Waḥdat al-Islāmiyya) is an internationalist and anti-nationalist political movement that advocates the unity of Muslims under one Islamic state, often a caliphate or an international organization with Islamic principles. Historically, after Ottomanism, which aimed at the unity of all Ottoman citizens, pan-Islamism was promoted in the Ottoman Empire during the last quarter of the 19th century by Sultan Abdul Hamid II for the purpose of preventing secession movements of the Muslim peoples in the empire.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Pan-Islamism"},{"label":"Wikipedia — Pan-Islamism","url":"https://en.wikipedia.org/wiki/Pan-Islamism"}]},
  {"kind":"theory","name":"Pan-Turkism","classed":"political ideology","said":"Pan-Turkism (Turkish: Pan-Türkizm) or Turkism (Turkish: Türkçülük or Türkizm) is a political movement that emerged during the 1880s among Turkic intellectuals who lived in the Russian region of Kazan (Tatarstan), South Caucasus (modern-day Azerbaijan) and the Ottoman Empire (modern-day Turkey), with its aim being the cultural and political unification of all Turkic peoples. Turanism is a closely related movement but it is a more general term, because Turkism only applies to Turkic peoples.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Pan-Turkism"},{"label":"Wikipedia — Pan-Turkism","url":"https://en.wikipedia.org/wiki/Pan-Turkism"}]},
  {"kind":"theory","name":"Pancasila","classed":"political ideology","said":"Pancasila (Indonesian: [pantʃaˈsila] ) is the official, foundational philosophical theory and state ideology of Indonesia. The name is made from two words originally derived from Sanskrit: pañca 'five' and śīla 'principles; precepts'.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Pancasila"},{"label":"Wikipedia — Pancasila","url":"https://en.wikipedia.org/wiki/Pancasila"}]},
  {"kind":"theory","name":"Peaceful coexistence","classed":"political ideology","said":"Peaceful coexistence (Russian: мирное сосуществование, romanized: mirnoye sosushchestvovaniye) was a theory, developed and applied by the Soviet Union at various points during the Cold War in the context of primarily Marxist–Leninist foreign policy and adopted by Soviet-dependent socialist states, according to which the Socialist Bloc could peacefully coexist with the capitalist bloc (i.e., U.S.-allied states). This was in contrast to the antagonistic contradiction principle that socialism and capitalism could never coexist in peace.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/peaceful-coexistence"},{"label":"Wikipedia — Peaceful coexistence","url":"https://en.wikipedia.org/wiki/Peaceful_coexistence"}]},
  {"kind":"theory","name":"Peronism","classed":"political ideology","said":"Peronism, also known as justicialism, is an Argentine ideology and political movement, based on the ideas, doctrine, and legacy of Juan Perón (1895–1974). It has been an influential movement in 20th- and 21st-century Argentine politics. Since 1946, Peronists have won 10 out of the 14 presidential elections in which they have been allowed to run.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Peronist"},{"label":"Wikipedia — Peronism","url":"https://en.wikipedia.org/wiki/Peronism"}]},
  {"kind":"theory","name":"Phyletism","classed":"political ideology","said":"Phyletism or ethnophyletism (from Ancient Greek: ἔθνος, romanized: ethnos, lit. 'nation' and φυλετικός, phyletikos, 'tribal') is the principle of nationalities applied in the ecclesiastical domain: in other words, the conflation between church and nation. The term ethnophyletism designates the idea that a local autocephalous church should be based not on a local (ecclesial) criterion, but on an ethnophyletist, national or linguistic one.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/phyletism"},{"label":"Wikipedia — Phyletism","url":"https://en.wikipedia.org/wiki/Phyletism"}]},
  {"kind":"theory","name":"Plato's political philosophy","classed":"political philosophy","said":"In Plato's Republic, the character of Socrates is highly critical of democracy and instead proposes, as an ideal political state, a hierarchal system of three classes: philosopher-kings or guardians who make the decisions, soldiers or \"auxiliaries\" who protect the society, and producers who create goods and do other work. Despite the title Republic (in Ancient Greek Politeia—Πολιτεία—and then translated through Latin into English), Plato's characters do not propose a republic in the modern English sense of the word.","sources":[{"label":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/platopol/"},{"label":"Wikipedia — Plato's political philosophy","url":"https://en.wikipedia.org/wiki/Plato's_political_philosophy"}]},
  {"kind":"theory","name":"Pluralism (political philosophy)","classed":"political philosophy","said":"Pluralism is a political philosophy that holds that diversity within a political body allows different interests, convictions, ideologies, and lifestyles to coexist peacefully. While not all political pluralists advocate for a pluralist democracy, this is the most common stance, because democracy is often viewed as the fairest and most effective way to balance discrete values.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/pluralism-politics"},{"label":"Wikipedia — Pluralism (political philosophy)","url":"https://en.wikipedia.org/wiki/Pluralism_(political_philosophy)"}]},
  {"kind":"theory","name":"Populism","classed":"political ideology","said":"Populism is a contested concept for a variety of political stances that emphasise the idea of the \"common people\", often in opposition to a perceived elite. It is frequently associated with anti-establishment and anti-political sentiment. The term developed in the late 19th century and has been applied to various politicians, parties, and movements since that time, often assuming a pejorative tone. Within political science and other social sciences, different definitions of populism have been employed.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/populism"},{"label":"Wikipedia — Populism","url":"https://en.wikipedia.org/wiki/Populism"}]},
  {"kind":"theory","name":"Progressivism","classed":"political ideology","said":"Progressivism is a political philosophy that seeks to make progress in the human condition through reforms aimed at increasing positive liberty. Progressivism arose during the Age of Enlightenment out of the belief that civility in Europe was improving due to the application of new empirical knowledge. Progressivism as an umbrella term is associated with variants of social liberalism, social democracy and democratic socialism. Within economic progressivism, there is some ideological variation. Illustrative examples of this include some Christian democracy and conservative-leaning communitarian movements.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/progressive-movement-sociology"},{"label":"Wikipedia — Progressivism","url":"https://en.wikipedia.org/wiki/Progressivism"}]},
  {"kind":"theory","name":"Protectionism","classed":"political ideology","said":"Protectionism, sometimes referred to as trade protectionism, is the economic policy of restricting imports from other countries through methods such as tariffs on imported goods, import quotas, and a variety of other government regulations. Proponents argue that protectionist policies shield the producers, businesses, and workers of the import-competing sector in the country from foreign competitors and raise government revenue.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/protectionism"},{"label":"Wikipedia — Protectionism","url":"https://en.wikipedia.org/wiki/Protectionism"}]},
  {"kind":"theory","name":"Proto-fascism","classed":"political ideology","said":"Proto-fascism represents the direct predecessor ideologies and cultural movements that influenced and formed the basis of fascism. The term protofascism is also used in a slightly more general sense to refer to any political movement whose activities make the emergence of fascism more likely.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/protofascism"},{"label":"Wikipedia — Proto-fascism","url":"https://en.wikipedia.org/wiki/Proto-fascism"}]},
  {"kind":"theory","name":"Racism","classed":"political ideology","said":"Racism is the belief that groups of humans possess different behavioral traits corresponding to inherited attributes and can be divided based on the superiority of one race or ethnicity over another. It may also mean prejudice, discrimination, or antagonism directed against other people because they are of a different ethnic background. Modern variants of racism are often based in social perceptions of biological differences between peoples.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/racism"},{"label":"Wikipedia — Racism","url":"https://en.wikipedia.org/wiki/Racism"}]},
  {"kind":"theory","name":"Radical politics","classed":"political ideology","said":"Radical politics denotes the intent to transform or replace the fundamental principles of a society or political system, often through social change, structural change, revolution or radical reform. The process of adopting radical views is termed radicalisation. The word radical derives from the Latin radix (\"root\") and Late Latin radicalis (\"of or pertaining to the root, radical\"). Historically, political use of the term referred exclusively to a form of progressive electoral reformism, known as classical radicalism, that had developed in Europe during the 18th and 19th centuries.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/radicalism-politics"},{"label":"Wikipedia — Radical politics","url":"https://en.wikipedia.org/wiki/Radical_politics"}]},
  {"kind":"theory","name":"Regionalism (politics)","classed":"political ideology","said":"Regionalism is a political ideology that seeks to increase the political power, influence and self-determination of the people of one or more subnational regions. It focuses on the \"development of a political or social system based on one or more\" regions, and/or the national, normative, or economic interests of a specific region, group of regions or another subnational entity, gaining strength from or aiming to strengthen the \"consciousness of and loyalty to a distinct region with a homogeneous population\", similarly to nationalism.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/regionalism-anthropology"},{"label":"Wikipedia — Regionalism (politics)","url":"https://en.wikipedia.org/wiki/Regionalism_(politics)"}]},
  {"kind":"theory","name":"Republicanism","classed":"political ideology","said":"Republicanism is a political ideology that promotes the republican system of government, in which sovereignty resides in the people and their elected representatives, as opposed to hereditary monarchy or other forms of absolute personal power. It is founded on several key principles, including civic virtue, active political participation, civic education, the fight against corruption (anti-corruption), a preference for a balanced and mixed constitution, government limited by constitutional laws, freedom as non-domination, and a commitment to the rule of law and the common good.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/republicanism/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/republicanism"},{"label":"Wikipedia — Republicanism","url":"https://en.wikipedia.org/wiki/Republicanism"}]},
  {"kind":"theory","name":"Revisionism (Marxism)","classed":"political ideology","said":"In Marxist philosophy, revisionism is a pejorative label given to various ideas, principles, and theories that are based on a fundamental reinterpretation of Marxism. According to critics of revisionism, this involves a significant deviation from mainstream Marxist tendencies, such as classical Marxism and orthodox Marxism, or a specific ideology held by the accuser, such as Marxism–Leninism, Maoism, Left Communism, or Trotskyism. The characteristics most attributed to revisionist Marxisms are the formation of an alliance with the bourgeoisie and rejecting the centrality of revolution in favor of reformism.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/revisionism-Marxism"},{"label":"Wikipedia — Revisionism (Marxism)","url":"https://en.wikipedia.org/wiki/Revisionism_(Marxism)"}]},
  {"kind":"theory","name":"Right-wing antiglobalism","classed":"political ideology","said":"Right-wing antiglobalism, also referred to as the antiglobalist right, is a political position opposing Globalism, arguing national identities and economies are encroached on by incessant immigration. Right-wing antiglobalists support nationalism as a cure for the alleged problems caused by the globalization. Right-wing antiglobalism protests against the United Nations (including its Sustainable Development Goals), 15-minute cities, and COVID-19 vaccines as being created or promoted by globalists.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/antiglobalization/Right-and-left-wing-antiglobalism"},{"label":"Wikipedia — Right-wing antiglobalism","url":"https://en.wikipedia.org/wiki/Right-wing_antiglobalism"}]},
  {"kind":"theory","name":"Saint-Simonianism","classed":"political ideology","said":"Saint-Simonianism () was a French political, religious and social movement of the first half of the 19th century, inspired by the ideas of Claude Henri de Rouvroy, comte de Saint-Simon. His ideas focused on the perception that growth in industrialization and scientific discovery would cause profound changes in society. He believed that society would restructure itself by abandoning traditional ideas of temporal and spiritual power. An evolution that would lead, inevitably, to a productive society based on and benefiting from, a \"... union of men engaged in useful work\", the basis of \"true equality\".","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Saint-Simonianism"},{"label":"Wikipedia — Saint-Simonianism","url":"https://en.wikipedia.org/wiki/Saint-Simonianism"}]},
  {"kind":"theory","name":"Scientific racism","classed":"political ideology","said":"Scientific racism, sometimes termed biological racism, is the pseudoscientific belief that the human species is divided into biologically distinct taxa called \"races\", and that empirical evidence exists to support or justify racial discrimination, racial inferiority, or racial superiority. Modern scientific consensus rejects this view as being irreconcilable with genetic research.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/scientific-racism"},{"label":"Wikipedia — Scientific racism","url":"https://en.wikipedia.org/wiki/Scientific_racism"}]},
  {"kind":"theory","name":"Scientific socialism","classed":"political ideology","said":"Scientific socialism in Marxism is the application of historical materialism to the development of socialism, as not just a practical and achievable outcome of historical processes, but the only possible outcome. It contrasts with utopian socialism by basing itself upon material conditions instead of concoctions and ideas, where \"the final causes of all social changes and political revolutions are to be sought, not in men's brains, not in men's better insights into eternal truth and justice, but in changes in the modes of production and exchange.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/scientific-socialism"},{"label":"Wikipedia — Scientific socialism","url":"https://en.wikipedia.org/wiki/Scientific_socialism"}]},
  {"kind":"theory","name":"Separation of powers","classed":"political philosophy","said":"The separation of powers principle functionally differentiates several types of state power (usually legislation, adjudication, and execution) and requires these operations of government to be conceptually and institutionally distinct and clearly articulated, thereby maintaining the integrity of each branch. Separation of powers is closely linked to notions of checks and balances.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/separation-of-powers"},{"label":"Wikipedia — Separation of powers","url":"https://en.wikipedia.org/wiki/Separation_of_powers"}]},
  {"kind":"theory","name":"Separatism","classed":"political ideology","said":"Separatism is the advocacy of cultural, ethnic, tribal, religious, racial, regional, governmental, or gender separation from the larger group. As with secession, separatism conventionally refers to full political separation. Groups simply seeking greater autonomy are usually not considered separatists. Some discourse settings equate separatism with religious segregation, racial segregation, or sex segregation, while other discourse settings take the broader view that separation by choice may serve useful purposes and is not the same as government-enforced segregation.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/separatism"},{"label":"Wikipedia — Separatism","url":"https://en.wikipedia.org/wiki/Separatism"}]},
  {"kind":"theory","name":"Social credit","classed":"political philosophy","said":"Social credit is a distributive philosophy of political economy developed in the 1920s and 1930s by the British engineer and economist C. H. Douglas. Douglas attributed economic downturns to discrepancies between the cost of goods and the compensation of the workers who made them. To combat what he saw as a chronic deficiency of purchasing power in the economy, Douglas prescribed government intervention in the form of the issuance of debt-free money directly to consumers or producers (if they sold their product below cost to consumers) in order to combat such discrepancy.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Social-Credit-political-economics"},{"label":"Wikipedia — Social credit","url":"https://en.wikipedia.org/wiki/Social_credit"}]},
  {"kind":"theory","name":"Social democracy","classed":"political ideology","said":"Social democracy is a broad, centre-left social, economic, and political ideology. Some academics view social democracy as distinct from socialism, whilst other academics purport that social democracy lies within the wider socialist movement. Social democracy supports political and economic democracy and a gradualist, reformist, and democratic approach toward achieving social equality. In modern practice, social democracy has taken the form of a predominantly capitalist, yet robust welfare state, with policies promoting social justice, market regulation, and a more equitable distribution of income.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/social-democracy"},{"label":"Wikipedia — Social democracy","url":"https://en.wikipedia.org/wiki/Social_democracy"}]},
  {"kind":"theory","name":"Socialism","classed":"political ideology","said":"Socialism is an economic ideology and political philosophy encompassing diverse economic and social systems characterised by social ownership of the means of production, as opposed to private ownership. It describes the economic, political, and social theories and movements associated with the implementation of such systems. Social ownership can take various forms, including public, community, collective, cooperative, or employee. As one of the main ideologies on the political spectrum, socialism is the standard left-wing ideology in most countries.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/socialism/"},{"label":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/socialis/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/socialism"},{"label":"Wikipedia — Socialism","url":"https://en.wikipedia.org/wiki/Socialism"}]},
  {"kind":"theory","name":"Socialist feminism","classed":"political ideology","said":"Socialist feminism rose in the 1960s and 1970s as an offshoot of the feminist movement and New Left that focuses upon the interconnectivity of the patriarchy and capitalism. However, the ways in which women's private, domestic, and public roles in society has been conceptualized, or thought about, can be traced back to Mary Wollstonecraft's A Vindication of the Rights of Woman (1792) and William Thompson's utopian socialist work in the 19th century. Ideas about overcoming the patriarchy by coming together in female groups to talk about personal problems stem from Carol Hanisch.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/socialist-feminism"},{"label":"Wikipedia — Socialist feminism","url":"https://en.wikipedia.org/wiki/Socialist_feminism"}]},
  {"kind":"theory","name":"Sonnō jōi","classed":"political ideology","said":"Sonnō jōi (尊王攘夷; \"revere the emperor, expel the barbarians\") was a yojijukugo (four-character compound) phrase used as the rallying cry and slogan of a political movement in Japan in the 1850s and 1860s, during the Bakumatsu period. Based on Neo-Confucianism and Japanese nativism, the movement sought to overthrow the Tokugawa shogunate and restore the power of the Emperor of Japan.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Sonno-joi"},{"label":"Wikipedia — Sonnō jōi","url":"https://en.wikipedia.org/wiki/Sonn%C5%8D_j%C5%8Di"}]},
  {"kind":"theory","name":"Synarchism","classed":"political ideology","said":"Synarchism generally means \"joint rule\" or \"harmonious rule\". Beyond this general definition, both synarchism and synarchy have been used to denote rule by a secret elite in Vichy France, Italy, China, and Hong Kong, while also being used to describe a pro-Catholic theocracy movement in Mexico.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Sinarquism"},{"label":"Wikipedia — Synarchism","url":"https://en.wikipedia.org/wiki/Synarchism"}]},
  {"kind":"theory","name":"Technocracy","classed":"political ideology","said":"Technocracy is an expert-based type of governance. In its strongest sense, it is a form of government in which decisions across all sectors and policy domains follow evidence-based, efficiency-oriented procedures grounded in scientific methods and instrumental rationality. In a weaker sense, the term refers to hybrid models that delegate specific functions to experts or implement expertise-driven decision procedures in areas such as central banking, public health, or environmental regulation.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/technocracy"},{"label":"Wikipedia — Technocracy","url":"https://en.wikipedia.org/wiki/Technocracy"}]},
  {"kind":"theory","name":"Thatcherism","classed":"political ideology","said":"Thatcherism is a form of British conservative ideology named after Conservative Party leader Margaret Thatcher that relates to not just her political platform and particular policies, but also her personal character and style of management while in office. Proponents of Thatcherism are referred to as Thatcherites. The term has been used to describe the principles of the British government under Thatcher from the 1979 general election to her resignation in 1990.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Thatcherism"},{"label":"Wikipedia — Thatcherism","url":"https://en.wikipedia.org/wiki/Thatcherism"}]},
  {"kind":"theory","name":"Third Way","classed":"political ideology","said":"The Third Way is a predominantly centrist political position that attempts to reconcile centre-right and centre-left politics by synthesising a combination of economically liberal and social democratic economic policies. It is a reconceptualisation of social democracy. It supports workfare instead of welfare, work training programs, educational opportunities, and other government programs that give citizens a 'hand-up' instead of a 'hand-out'.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Third-Way-British-history"},{"label":"Wikipedia — Third Way","url":"https://en.wikipedia.org/wiki/Third_Way"}]},
  {"kind":"theory","name":"Three Principles of the People","classed":"political philosophy","said":"The Three Principles of the People (Chinese: 三民主義; pinyin: Sānmín Zhǔyì) refer to a nationalist, republican, anti-imperialist political ideology developed by Sun Yat-sen which consist of nationalism (民族主義), democracy (民權主義), and people's welfare (民生主義). The Principles were influenced by a broad set of influences, including Georgism, Marxism, and Chinese utopianism. Under Kuomintang rule, Sun's thought achieved canonical status as part of an overall cult of personality.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/Three-Principles-of-the-People"},{"label":"Wikipedia — Three Principles of the People","url":"https://en.wikipedia.org/wiki/Three_Principles_of_the_People"}]},
  {"kind":"theory","name":"Totalitarianism","classed":"political ideology","said":"Totalitarianism is a political system and a form of government that completely controls the public sphere and the private sphere of society. It is characterized by its prohibition of opposing political parties and its extreme suppression of opposition to the state. In the field of political science, totalitarianism is the extreme form of authoritarianism, wherein all political power is held by a dictator. This figure controls the national politics and peoples of the nation with continual propaganda campaigns that are broadcast by state-controlled and state-aligned private mass communications media.","sources":[{"label":"Internet Encyclopedia of Philosophy","url":"https://iep.utm.edu/totalita/"},{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/totalitarianism"},{"label":"Wikipedia — Totalitarianism","url":"https://en.wikipedia.org/wiki/Totalitarianism"}]},
  {"kind":"theory","name":"Trotskyism","classed":"political ideology","said":"Trotskyism (Russian: Троцкизм, romanized: Trotskizm) is the political ideology and branch of Marxism and Leninism developed by Russian revolutionary and intellectual Leon Trotsky along with some other members of the Left Opposition and the Fourth International. Trotsky described himself as an orthodox Marxist, a revolutionary Marxist, and a Bolshevik–Leninist as well as a follower of Karl Marx, Friedrich Engels, Vladimir Lenin, Karl Liebknecht, and Rosa Luxemburg. His relations with Lenin have been a source of intense historical debate.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Trotskyism"},{"label":"Wikipedia — Trotskyism","url":"https://en.wikipedia.org/wiki/Trotskyism"}]},
  {"kind":"theory","name":"Turanism","classed":"political ideology","said":"Turanism, also known as Turanianism, pan-Turanism or pan-Turanianism, is a pan-nationalist political movement built around pseudoscientific claims of biological and linguistic connections between various ethnic groups of Eurasia. It revolves around the notion that Turkic, Mongolic, Tungusic, and Uralic peoples share close cultural, ethnic, and linguistic bonds due to Inner and Central Asian origins. Historically, one of its central components was the proposal of a Ural-Altaic language family, which has since been abandoned.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/event/Pan-Turanianism"},{"label":"Wikipedia — Turanism","url":"https://en.wikipedia.org/wiki/Turanism"}]},
  {"kind":"theory","name":"Ultramontanism","classed":"political ideology","said":"Ultramontanism is a clerical-political conception within the Catholic Church that places strong emphasis on (and expresses loyalty to) the prerogatives and powers of the Pope in matters related to civil state governance. It contrasts with Gallicanism, the belief that popular civil authority – often represented by the monarch's or state's authority – over the Church is comparable to that of the Pope.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Ultramontanism"},{"label":"Wikipedia — Ultramontanism","url":"https://en.wikipedia.org/wiki/Ultramontanism"}]},
  {"kind":"theory","name":"Ultranationalism","classed":"political ideology","said":"Ultranationalism, or extreme nationalism, is an extremist form of nationalism in which a country asserts or maintains hegemony, supremacy, or other forms of control over other nations, to pursue its specific interests. Ultranationalist entities have been associated with the engagement of political violence even during peacetime.","sources":[{"label":"Stanford Encyclopedia of Philosophy","url":"https://plato.stanford.edu/entries/ultranationalism/"},{"label":"Wikipedia — Ultranationalism","url":"https://en.wikipedia.org/wiki/Ultranationalism"}]},
  {"kind":"theory","name":"Volksgemeinschaft","classed":"political ideology","said":"Volksgemeinschaft (German pronunciation: [ˈfɔlksɡəˌmaɪnʃaft] ) is a German expression meaning \"people's community\", \"folk community\", \"national community\", or \"racial community\", depending on the translation of its component term Volk (cognate with the English word \"folk\"). This expression originally became popular during World War I as Germans rallied in support of the war, and many experienced \"relief that at one fell swoop all social and political divisions could be solved in the great national equation\".","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Volksgemeinschaft"},{"label":"Wikipedia — Volksgemeinschaft","url":"https://en.wikipedia.org/wiki/Volksgemeinschaft"}]},
  {"kind":"theory","name":"Voluntaryism","classed":"political ideology","said":"Voluntaryism (UK:, US:; sometimes voluntarism ) is used to describe the philosophy of Auberon Herbert, and later that of the authors and supporters of The Voluntaryist magazine, which supports a voluntary-funded state (i.e. \"the Voluntary State\"), meaning a lack of coercion and force in matters such as taxation. This is conventionally completed through a strict adherence to pacifism, civil rights, and either arbitration or some other mutually-agreed-upon court system between individuals.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/voluntarism-philosophy"},{"label":"Wikipedia — Voluntaryism","url":"https://en.wikipedia.org/wiki/Voluntaryism"}]},
  {"kind":"theory","name":"White supremacy","classed":"political ideology","said":"White supremacy is the belief that white people are superior to those of other races. The belief favors the maintenance and defense of any power and privilege held by white people. White supremacy has roots in the now-discredited doctrine of scientific racism and was a key justification for European colonialism. As a political ideology, it imposes and maintains cultural, social, political, historical or institutional domination by white people and non-white supporters.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/white-supremacy"},{"label":"Wikipedia — White supremacy","url":"https://en.wikipedia.org/wiki/White_supremacy"}]},
  {"kind":"theory","name":"Yugoslavism","classed":"political ideology","said":"Yugoslavism, Yugoslavdom, or Yugoslav nationalism is an ideology supporting the notion that the South Slavs, namely the Bosniaks, Bulgarians, Croats, Macedonians, Montenegrins, Serbs, and Slovenes, belong to a single Yugoslav nation separated by diverging historical circumstances, forms of speech, and religious divides. During the interwar period, Yugoslavism became predominant in, and then the official ideology of, the Kingdom of Yugoslavia.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Yugoslavism"},{"label":"Wikipedia — Yugoslavism","url":"https://en.wikipedia.org/wiki/Yugoslavism"}]},
  {"kind":"theory","name":"Zionism","classed":"political ideology","said":"Zionism is an ethnic nationalist movement that emerged in late 19th-century Europe to establish and support a Jewish homeland through colonization in the region of Palestine, which roughly corresponds to the Land of Israel in Judaism—itself central to Jewish history. Zionists wanted to create a Jewish state in Palestine with as much land, as many Jews, and as few Palestinian Arabs as possible. Zionism was the main force behind the creation of the State of Israel in 1948, and remains the country's dominant ideology today.","sources":[{"label":"Encyclopaedia Britannica","url":"https://www.britannica.com/topic/Zionism"},{"label":"Wikipedia — Zionism","url":"https://en.wikipedia.org/wiki/Zionism"}]},
];
